    (() => {
      const fig = document.querySelector('.mech-figure');
      const svg = fig.querySelector('svg');
      const toggleBtn = fig.querySelector('[data-mech-toggle]');
      const themeBtn = fig.querySelector('[data-theme-toggle]');
      const statusEl = fig.querySelector('[data-mech-status]');
      const stageNodes = Array.from(fig.querySelectorAll('.mech-node[data-stage]'));
      const stageBtns = Array.from(fig.querySelectorAll('[data-stage-btn]'));

      const STAGE_COPY = {
        all: 'Showing all stages: Producer emits webhook events to Queue, Queue dispatches them to Worker, and failed deliveries branch to Retry DLQ.',
        producer: 'Stage 1 — Producer: Emits webhook events along the primary delivery track into the Queue.',
        queue: 'Stage 2 — Queue: Receives events from Producer, buffers them, and dispatches jobs to the Worker.',
        worker: 'Stage 3 — Worker: Consumes dispatched events from Queue for delivery and routes failed deliveries to Retry DLQ.',
        'retry-dlq': 'Branch — Retry DLQ: Captures failed deliveries routed from the Worker along the failed-delivery branch.'
      };

      const STAGE_ORDER = ['producer', 'queue', 'worker', 'retry-dlq'];
      const reducedQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
      const darkQuery = window.matchMedia('(prefers-color-scheme: dark)');

      function setPaused(paused, announce) {
        fig.dataset.paused = String(paused);
        toggleBtn.setAttribute('aria-pressed', String(paused));
        toggleBtn.textContent = paused ? 'Play animation' : 'Pause animation';
        if (typeof svg.pauseAnimations === 'function') {
          if (paused) {
            svg.pauseAnimations();
          } else {
            svg.unpauseAnimations();
          }
        }
        if (announce && statusEl) {
          if (reducedQuery.matches && !paused) {
            statusEl.textContent = 'System reduced-motion preference is active; static directional arrows remain visible.';
          } else {
            statusEl.textContent = paused
              ? 'Animation paused. Static directional arrows and numbered stages remain visible.'
              : 'Animation playing across Producer, Queue, Worker, and the Retry DLQ branch.';
          }
        }
      }

      if (reducedQuery.matches) {
        setPaused(true, false);
        if (statusEl) {
          statusEl.textContent = 'Reduced motion active: static directional arrows show Producer to Queue to Worker, with failed deliveries branching to Retry DLQ.';
        }
      }

      reducedQuery.addEventListener('change', (e) => {
        if (e.matches) {
          setPaused(true, true);
        }
      });

      toggleBtn.addEventListener('click', () => {
        const isPaused = fig.dataset.paused === 'true';
        setPaused(!isPaused, true);
      });

      function currentTheme() {
        const explicit = document.documentElement.dataset.theme;
        if (explicit === 'dark' || explicit === 'light') return explicit;
        return darkQuery.matches ? 'dark' : 'light';
      }

      function syncThemeButton() {
        const isDark = currentTheme() === 'dark';
        themeBtn.setAttribute('aria-pressed', String(isDark));
        themeBtn.textContent = isDark ? 'Switch to light' : 'Switch to dark';
      }

      syncThemeButton();
      darkQuery.addEventListener('change', syncThemeButton);

      themeBtn.addEventListener('click', () => {
        const next = currentTheme() === 'dark' ? 'light' : 'dark';
        document.documentElement.dataset.theme = next;
        syncThemeButton();
        if (statusEl) {
          statusEl.textContent = `Switched diagram theme to ${next} mode.`;
        }
      });

      function setActiveStage(stageId, moveNodeFocus = false) {
        if (!stageId || stageId === 'all') {
          delete fig.dataset.activeStage;
        } else {
          fig.dataset.activeStage = stageId;
        }

        const active = fig.dataset.activeStage || 'all';
        stageBtns.forEach((btn) => {
          btn.setAttribute('aria-pressed', String(btn.dataset.stageBtn === active));
        });
        stageNodes.forEach((node) => {
          node.setAttribute('aria-pressed', String(node.dataset.stage === active));
        });

        if (moveNodeFocus && active !== 'all') {
          const targetNode = stageNodes.find((n) => n.dataset.stage === active);
          if (targetNode) targetNode.focus();
        }

        if (statusEl) {
          statusEl.textContent = STAGE_COPY[active] || STAGE_COPY.all;
        }
      }

      stageBtns.forEach((btn) => {
        btn.addEventListener('click', () => {
          const target = btn.dataset.stageBtn;
          const next = target !== 'all' && fig.dataset.activeStage === target ? 'all' : target;
          setActiveStage(next, false);
        });
      });

      let activeBeforePointer = null;

      stageNodes.forEach((node) => {
        const stage = node.dataset.stage;
        node.addEventListener('pointerdown', () => {
          activeBeforePointer = fig.dataset.activeStage || 'all';
        });

        node.addEventListener('click', () => {
          const wasActive = activeBeforePointer === stage;
          activeBeforePointer = null;
          setActiveStage(wasActive ? 'all' : stage, false);
        });

        node.addEventListener('focus', () => {
          setActiveStage(stage, false);
        });

        node.addEventListener('keydown', (e) => {
          const idx = STAGE_ORDER.indexOf(stage);
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            const next = fig.dataset.activeStage === stage ? 'all' : stage;
            setActiveStage(next, false);
          } else if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
            e.preventDefault();
            const nextStage = STAGE_ORDER[(idx + 1) % STAGE_ORDER.length];
            setActiveStage(nextStage, true);
          } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
            e.preventDefault();
            const prevStage = STAGE_ORDER[(idx - 1 + STAGE_ORDER.length) % STAGE_ORDER.length];
            setActiveStage(prevStage, true);
          } else if (e.key === 'Home') {
            e.preventDefault();
            setActiveStage(STAGE_ORDER[0], true);
          } else if (e.key === 'End') {
            e.preventDefault();
            setActiveStage(STAGE_ORDER[STAGE_ORDER.length - 1], true);
          } else if (e.key === 'Escape') {
            e.preventDefault();
            setActiveStage('all', false);
            node.blur();
          }
        });
      });
    })();
  </script>
